UPDATE
	BOOK_PACKAGE_BUNDLE
SET
	book_package_bundle_title = #{book_package_bundle_title}
WHERE
	book_package_bundle_idx = #{book_package_bundle_idx}

mapper.select:
SELECT
a.homepage_id, a.book_package_bundle_idx, a.book_package_bundle_title, b.book_package_name, b.author, b.publisher, b.publish_year, a.loan_count, a.quantity, a.grade, b.category, b.keyword, b.desc_link, b.image_link, REGEXP_REPLACE(b.content, '<[^>]*>', '') AS content, b.org_file_name, b.server_file_name, b.file_extension, b.file_size, b.doc_org_file_name, b.doc_server_file_name, b.doc_file_extension, b.doc_file_size, b.book_package_bundle_detail_idx
FROM BOOK_PACKAGE_BUNDLE a, BOOK_PACKAGE_BUNDLE_DETAIL b WHERE a.homepage_id = #{homepage_id} AND a.book_package_bundle_idx = b.book_package_bundle_idx AND a.book_package_bundle_idx = #{book_package_bundle_idx}

mapper.update:
UPDATE
	BOOK_PACKAGE_BUNDLE_LOAN
SET
	return_yn = #{return_yn}
WHERE
	book_package_bundle_loan_idx = #{book_package_bundle_loan_idx}

mapper.select:
SELECT
	COUNT(*)
FROM
	BOOK_PACKAGE_BUNDLE a, BOOK_PACKAGE_BUNDLE_LOAN b
WHERE
	a.book_package_bundle_idx = b.book_package_bundle_idx

AND	${search_type} LIKE '%'||#{search_text}||'%'



	AND	return_yn = #{return_yn}
	AND	request_status = '2'


	AND	request_status = #{request_status}



AND	TO_CHAR(loan_start_date, 'yyyy') = #{loan_start_date}


AND b.add_id = #{add_id}

${pagingTop} SELECT b.book_package_bundle_idx, b.book_package_bundle_loan_idx, a.book_package_bundle_title, b.request_name, b.school_name, a.quantity, a.loan_count, TO_CHAR(b.loan_start_date, 'yyyy-MM-dd') AS loan_start_date, TO_CHAR(b.loan_end_date, 'yyyy-MM-dd') AS loan_end_date, b.phone, b.school_tel, b.request_content, b.request_status, b.return_yn, b.add_id, b.add_date, LISTAGG(c.category,',') WITHIN GROUP (ORDER BY c.book_package_bundle_idx ) AS category FROM BOOK_PACKAGE_BUNDLE a, BOOK_PACKAGE_BUNDLE_LOAN b, BOOK_PACKAGE_BUNDLE_DETAIL c WHERE a.book_package_bundle_idx = b.book_package_bundle_idx
AND ${search_type} LIKE '%'||#{search_text}||'%'
AND return_yn = #{return_yn} AND request_status = '2'
AND request_status = #{request_status}
AND TO_CHAR(loan_start_date, 'yyyy') = #{loan_start_date}
AND REGEXP_LIKE(category, REPLACE(#{category}, ',', '|'))
AND b.add_id = #{add_id}
GROUP BY b.book_package_bundle_idx, b.book_package_bundle_loan_idx, a.book_package_bundle_title, b.request_name, b.school_name, a.quantity, a.loan_count, b.loan_start_date, b.loan_end_date, b.phone, b.school_tel, b.request_content, b.request_status, b.return_yn, b.add_id, b.add_date ORDER BY b.book_package_bundle_loan_idx DESC ${pagingBottom}

SELECT
a.homepage_id, a.book_package_bundle_idx, a.book_package_bundle_title, b.book_package_name, b.author, b.publisher, b.publish_year, a.loan_count, a.quantity, a.grade, b.category, b.keyword, b.desc_link, b.image_link, REGEXP_REPLACE(b.content, '<[^>]*>', '') AS content, b.org_file_name, b.server_file_name, b.file_extension, b.file_size, b.doc_org_file_name, b.doc_server_file_name, b.doc_file_extension, b.doc_file_size
FROM BOOK_PACKAGE_BUNDLE a, BOOK_PACKAGE_BUNDLE_DETAIL b WHERE a.homepage_id = #{homepage_id} AND a.book_package_bundle_idx = b.book_package_bundle_idx AND b.book_package_bundle_detail_idx = #{book_package_bundle_detail_idx}
